async function scanBundle(input, deliver) {
  let line = 1;
  let delivered = 0;
  let buffer = new Uint8Array(0);
  let buffered = 0;
  const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

  function append(chunk, start, end) {
    const count = end - start;
    if (count === 0) return;

    const needed = buffered + count;
    if (needed > buffer.length) {
      const capacity = Math.max(needed, buffer.length ? buffer.length * 2 : 1024);
      const next = new Uint8Array(capacity);
      next.set(buffer.subarray(0, buffered));
      buffer = next;
    }

    buffer.set(chunk.subarray(start, end), buffered);
    buffered = needed;
  }

  async function finishLine(hasTerminator) {
    let length = buffered;
    if (hasTerminator && length > 0 && buffer[length - 1] === 0x0d) {
      length -= 1;
    }

    const text = decoder.decode(buffer.subarray(0, length));
    buffered = 0;
    if (buffer.length > 65536) buffer = new Uint8Array(0);

    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${line}`);
      error.code = "BAD_LINE";
      error.line = line;
      throw error;
    }

    delivered += 1;
    return (await deliver(value, line)) !== false;
  }

  try {
    for (;;) {
      const chunk = await input.read();
      if (chunk === null) break;

      let start = 0;
      for (let index = 0; index < chunk.length; index += 1) {
        if (chunk[index] !== 0x0a) continue;

        append(chunk, start, index);
        if (!(await finishLine(true))) return delivered;

        line += 1;
        start = index + 1;
      }

      append(chunk, start, chunk.length);
    }

    if (buffered > 0) {
      await finishLine(false);
    }

    return delivered;
  } finally {
    await input.close();
  }
}
